"""Portable checks for the script generated by the macOS installer."""

import json
import unittest
from pathlib import Path
from unittest.mock import patch

from webapp.install_desktop import launcher_script, main


class DesktopInstallerTests(unittest.TestCase):
    def test_quotes_paths_and_detaches_stdin_stdout_stderr(self):
        script = launcher_script(
            Path("/tmp/Alan's research"), "/tmp/My Python/bin/python", Path("/tmp/Local Data")
        )
        self.assertIn("/bin/sh -c", script)
        self.assertIn("webapp.server --port 18765 --open", script)
        command = json.loads(script.split("do shell script ", 1)[1].split("\nend run", 1)[0])
        self.assertIn("2>&1 < /dev/null &", command)
        self.assertTrue(command.endswith("> /dev/null 2>&1 < /dev/null"))
        self.assertIn("My Python", command)

    def test_non_macos_returns_actionable_error(self):
        with (
            patch("webapp.install_desktop.sys.platform", "linux"),
            self.assertRaisesRegex(SystemExit, "tradingagents-web --open"),
        ):
            main()
